From 586745f1598ccf71b0a5a6df2222dee0a865954e Mon Sep 17 00:00:00 2001
From: yu kuai <yukuai3@huawei.com>
Date: Thu, 4 Jun 2020 20:42:06 +0800
Subject: [PATCH] ARM: imx5: add missing put_device() call in
 imx_suspend_alloc_ocram()

if of_find_device_by_node() succeed, imx_suspend_alloc_ocram() doesn't
have a corresponding put_device(). Thus add a jump target to fix the
exception handling for this function implementation.

Fixes: 1579c7b9fe01 ("ARM: imx53: Set DDR pins to high impedance when in suspend to RAM.")
Signed-off-by: yu kuai <yukuai3@huawei.com>
Signed-off-by: Shawn Guo <shawnguo@kernel.org>

diff --git a/arch/arm/mach-imx/pm-imx5.c b/arch/arm/mach-imx/pm-imx5.c
index f057df813f83..e9962b48e30c 100644
--- a/arch/arm/mach-imx/pm-imx5.c
+++ b/arch/arm/mach-imx/pm-imx5.c
@@ -295,14 +295,14 @@ static int __init imx_suspend_alloc_ocram(
 	if (!ocram_pool) {
 		pr_warn("%s: ocram pool unavailable!\n", __func__);
 		ret = -ENODEV;
-		goto put_node;
+		goto put_device;
 	}

 	ocram_base = gen_pool_alloc(ocram_pool, size);
 	if (!ocram_base) {
 		pr_warn("%s: unable to alloc ocram!\n", __func__);
 		ret = -ENOMEM;
-		goto put_node;
+		goto put_device;
 	}

 	phys = gen_pool_virt_to_phys(ocram_pool, ocram_base);
@@ -312,6 +312,8 @@ static int __init imx_suspend_alloc_ocram(
 	if (virt_out)
 		*virt_out = virt;

+put_device:
+	put_device(&pdev->dev);
 put_node:
 	of_node_put(node);

-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The function `imx_suspend_alloc_ocram()` did not have a corresponding `put_device()` call when `of_find_device_by_node()` succeeded, leading to a potential memory leak or resource mismanagement if the function exited without releasing the device reference. This oversight could result in the device reference remaining allocated even after it was no longer needed, causing issues in resource management.

        Commit message:
        ARM: imx5: add missing put_device() call in
 imx_suspend_alloc_ocram()

if of_find_device_by_node() succeed, imx_suspend_alloc_ocram() doesn't
have a corresponding put_device(). Thus add a jump target to fix the
exception handling for this function implementation.

Fixes: 1579c7b9fe01 ("ARM: imx53: Set DDR pins to high impedance when in suspend to RAM.")
Signed-off-by: yu kuai <yukuai3@huawei.com>
Signed-off-by: Shawn Guo <shawnguo@kernel.org>  

        Patch:

 static int __init imx_suspend_alloc_ocram(
 				size_t size,
 				void __iomem **virt_out,
 				phys_addr_t *phys_out)
 {
 	struct device_node *node;
 	struct platform_device *pdev;
 	struct gen_pool *ocram_pool;
 	unsigned long ocram_base;
 	void __iomem *virt;
 	phys_addr_t phys;
 	int ret = 0;

 	/* Copied from imx6: TODO factorize */
 	node = of_find_compatible_node(NULL, NULL, "mmio-sram");
 	if (!node) {
 		pr_warn("%s: failed to find ocram node!\n", __func__);
 		return -ENODEV;
 	}

 	pdev = of_find_device_by_node(node);
 	if (!pdev) {
 		pr_warn("%s: failed to find ocram device!\n", __func__);
 		ret = -ENODEV;
 		goto put_node;
 	}

 	ocram_pool = gen_pool_get(&pdev->dev, NULL);
 	if (!ocram_pool) {
 		pr_warn("%s: ocram pool unavailable!\n", __func__);
 		ret = -ENODEV;
-		goto put_node;
+		goto put_device;
 	}

 	ocram_base = gen_pool_alloc(ocram_pool, size);
 	if (!ocram_base) {
 		pr_warn("%s: unable to alloc ocram!\n", __func__);
 		ret = -ENOMEM;
-		goto put_node;
+		goto put_device;
 	}

 	phys = gen_pool_virt_to_phys(ocram_pool, ocram_base);
 	virt = __arm_ioremap_exec(phys, size, false);
 	if (phys_out)
 		*phys_out = phys;
 	if (virt_out)
 		*virt_out = virt;

+put_device:
+	put_device(&pdev->dev);
 put_node:
 	of_node_put(node);

 	return ret;
 }



